import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·3","description":"易小帖 - 卷二·3","frontmatter":{"title":"卷二·3","description":"易小帖 - 卷二·3"},"headers":[],"relativePath":"classics/yixiaotie/043.md","filePath":"classics/yixiaotie/043.md"}'),o={name:"classics/yixiaotie/043.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·3",tabindex:"-1"},[r("卷二·3 "),e("a",{class:"header-anchor",href:"#卷二·3","aria-label":"Permalink to “卷二·3”"},"​")],-1),e("p",null,"「帝乙歸妹」《程傳》以帝乙為成湯，又為祖乙。按：紂父名帝乙，成湯名天乙。天乙、祖乙自皆與帝乙不同。但《乾鑿度》雲：易之帝乙為成湯，書之帝乙六世王，同名不害以明功。又曰：湯以乙生，嫁妹本天地正夫婦。則當時原有以帝乙屬成湯者。觀《後漢‧荀爽傳》其對策引易有雲：帝乙歸妹，以祉元吉。婦人謂嫁曰歸，言湯以娶禮歸其妹於諸侯是也。惟《左傳》杜註則指定微子之父，與虞氏易曰紂父正同。此是正解。若又曰祖乙，此即《鑿度》所雲六世王者。商自湯至祖乙，雖有十餘帝，而父子相嬗，祗得六世，則正指其人。要知，天乙祖乙原非帝乙。第漢儒解易，必謂文王口中或不應斥言近帝，則寧將三乙溷稱之，而後儒冒昧，即亦相習不察耳。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
